/**
 * dsh-web-file-preview — 文件预览分组判定（双端共用单一事实源）。
 *
 * 宿主（src/mime.ts）与浏览器端（src/renderer.ts、src/client.ts）统一复用
 * 本模块：后缀 → 预览分组，杜绝双端各写一份后缀表导致的漂移。
 * 纯逻辑、无 node/browser 特定 API，宿主 tsc 与浏览器 esbuild 均可打包。
 */

/** 预览分组：web 端能否渲染 + 渲染方式。 */
export type PreviewGroupKind = "image" | "md" | "code" | "text" | "html" | "other";

/** 分组判定结果。 */
export interface GroupOfResult {
  group: PreviewGroupKind;
  /** 归一化小写扩展名（不含点）。 */
  ext: string;
}

/** web 端可解码的图片后缀（收窄到浏览器能直接放的集合）。 */
export const IMAGE_EXTS = new Set(["png", "jpg", "jpeg", "gif", "webp", "svg", "avif", "bmp", "ico"]);

/** Markdown 渲染组。 */
export const MD_EXTS = new Set(["md", "markdown"]);

/**
 * HTML 渲染组（issue #73）：`.html/.htm` 从代码组迁出——走「serve 路由 + iframe
 * sandbox」静态伺服渲染，而非高亮源码直出。`/file` 仍以 text/plain 服务原始源码
 * （E2：保持 text/plain，避免顶层导航成为同源脚本执行通道）。
 */
export const HTML_EXTS = new Set(["html", "htm"]);

/** 代码渲染组（与客户端语言映射一致，见 src/code.ts）。 */
export const CODE_EXTS = new Set([
  "js", "mjs", "cjs", "ts", "tsx", "jsx", "py", "java", "c", "cc", "cpp",
  "h", "hh", "hpp", "cs", "go", "rs", "php", "rb", "kotlin", "kt", "swift",
  "dart", "scala", "sh", "bash", "zsh", "sql", "diff", "patch", "dockerfile",
  "ini", "toml", "yaml", "yml", "json", "jsonl", "xml", "css",
  "scss", "less", "vue", "svelte", "groovy", "perl", "r",
]);

/** 其它纯文本后缀。 */
export const TEXT_EXTS = new Set([
  "txt", "log", "conf", "cfg", "csv", "tsv", "env", "gitignore", "npmrc",
  "properties", "text", "plain", "me", "license", "todo",
]);

/** 本地扩展名提取（不依赖 node:path，供浏览器端打包）。 */
export function extOf(path: string): string {
  const base = (path.split(/[\\/]/).pop() ?? "").trim();
  const dot = base.lastIndexOf(".");
  return dot > 0 ? base.slice(dot + 1).toLowerCase() : "";
}

/** 按扩展名判定预览分组（未知 → other）。 */
export function groupOfExt(ext: string): PreviewGroupKind {
  if (IMAGE_EXTS.has(ext)) return "image";
  if (MD_EXTS.has(ext)) return "md";
  if (HTML_EXTS.has(ext)) return "html";
  if (CODE_EXTS.has(ext)) return "code";
  if (TEXT_EXTS.has(ext)) return "text";
  return "other";
}

/** 按路径（basename 扩展名）判定预览分组。 */
export function groupOfPath(path: string): GroupOfResult {
  const ext = extOf(path);
  return { group: groupOfExt(ext), ext };
}

/** 是否属于 web 端可预览分组（image | md | code | text）。 */
export function isPreviewablePath(path: string): boolean {
  return groupOfPath(path).group !== "other";
}

/**
 * 一个字符串是否呈现为"单个可预览文件路径"（供点击识别共用判定）。
 *
 * 识别"单个文件"而非"多个路径并列/拼接的展示标签"：逗号、换行、多段连续空白
 * 都是多文件并列的形态（如上下文注入折叠摘要 `~/.dsh/AGENTS.md, AGENTS.md`），
 * 误判会把它们当成一条路径去预览并拦截原生点击。http/#/mailto 与不可预览后缀
 * 一并排除。权威信号（元素 title / <a href>）与非权威文本嗅探共用此判定，
 * 保持双端一致、单一事实源。
 */
export function isLikelySingleFilePath(value: string): boolean {
  if (value === undefined || value === null) return false;
  if (/^https?:\/\//i.test(value) || value.startsWith("#") || value.startsWith("mailto:")) return false;
  if (value.includes(",")) return false;
  if (/[\n\r]/.test(value)) return false;
  if (/\s{2,}/.test(value)) return false;
  // 评审 U5：单空格分隔的多文件并列（`dir/a.md dir/b.md`）——每段都带路径分隔符时
  // 判定为拼接标签而非单路径，避免 stat 404 弹「打不开」。文件名本身含空格的
  // （`my file.md`）其后段无分隔符，不受影响。
  const spaceParts = value.split(" ");
  if (spaceParts.length > 1 && spaceParts.every((p) => p.length > 0 && /[\\/]/.test(p))) return false;
  if (!isPreviewablePath(value)) return false;
  return value.includes("/") || value.includes("\\") || !/\s/.test(value);
}

/**
 * 从对话渲染的 @-mention chip 标签还原干净文件路径（formatFileMention 的逆）。
 * dsh rc8 引入 `@` 引用后，对话气泡把 `@path` 渲染成带 `data-ref-chip` 的 span，
 * title 始终带前导 `@`（如 `@/abs/path/file.ts`）。
 * 本函数负责去掉前导 `@` 和可选的引号，还原出干净路径供预览引擎使用。
 *
 * @param raw - chip 的 title 属性，如 "@/abs/path/file.ts" 或 '@"a b/c.ts"'。
 * @param appearance - chip 的 data-ref-chip 取值。
 * @returns 干净路径；非文件类或无法解析 → null。
 */
export function cleanRefChipPath(raw: string, appearance: 'file' | 'folder' | 'session' | 'skill'): string | null {
  if (appearance === 'session' || appearance === 'skill') return null;
  if (typeof raw !== 'string' || raw === '') return null;
  let s = raw.startsWith('@') ? raw.slice(1) : raw;        // 去一个前导 @
  if (s.startsWith('"') && s.endsWith('"')) s = s.slice(1, -1); // 去引号（含空格路径）
  if (s === '') return null;
  return s; // folder 保留尾 /；file 由 formatFileMention 保证无尾 /
}

packages/dsh-web-file-preview/src/index..source:
/**
 * dsh-web-file-preview — 组合根（宿主端）。
 *
 * 让 web 端点击对话里的文件链接即可在浏览器内预览：
 *  - 宿主端注册 /api/dsh-file-preview/file（loopback 围栏，按 cwd 防穿越，
 *    图片直出 / 文本 UTF-8 直出）；
 *  - 客户端拦截对话中可点击的文件链接，弹出预览 Modal（见 src/client.ts）。
 *
 * 最小可行性版（MVP）：只做"文件内容服务 + 前端预览"，不校验路径是否属于
 * 已登记工作区——访问控制由平台/用户负责，本插件不做重复兜底。
 *
 * 激活：安装进 profile（见 cordis.patch.yml），重启一次 dsh web 生效。
 */

// 官方类型层（issue #16/#48，锁版见 pnpm-workspace catalog；仅 import type，
// 编译期擦除，禁止运行时值导入——contract-check 有门禁）。dsh-host-webserver
// 经 declare module 注入 ctx.webServer，必须引入其类型面。
import type { Context } from "@deepseek-ai/cordis";
import type {} from "@deepseek-ai/dsh-host-webserver";
import { makeRoutes, type PreviewConfig } from "./routes.ts";

/** 稳定的 cordis 插件名。 */
export const name = "web-file-preview";

/** 需要已初始化的 web 服务器。 */
export const inject = ["webServer"];

/** 默认配置。 */
export const DEFAULT_CONFIG: Required<PreviewConfig> = {
  enabled: true,
  // issue #344：文本类预览上限 512KB → 20M（超限仍 413 + truncated，语义不变；
  // 客户端对超大文本降级为纯 <pre> 截断渲染，见 render-limit.ts）。
  maxTextBytes: 20 * 1024 * 1024,
  // issue #73 D3 + #344：与 maxTextBytes 对称（20M）——serve 单资源上限，超限 413。
  maxAssetBytes: 20 * 1024 * 1024,
};

/** 归一化配置：只接受合法值，非法丢弃回默认。 */
export function normalizeConfig(config: PreviewConfig | undefined): PreviewConfig {
  const result: PreviewConfig = { ...DEFAULT_CONFIG };
  if (config !== undefined && typeof config === "object") {
    if (typeof config.enabled === "boolean") result.enabled = config.enabled;
    if (
      typeof config.maxTextBytes === "number" &&
      Number.isFinite(config.maxTextBytes) &&
      config.maxTextBytes > 0
    ) {
      result.maxTextBytes = config.maxTextBytes;
    }
    if (
      typeof config.maxAssetBytes === "number" &&
      Number.isFinite(config.maxAssetBytes) &&
      config.maxAssetBytes > 0
    ) {
      result.maxAssetBytes = config.maxAssetBytes;
    }
  }
  return result;
}

/** 插件 apply：薄壳，只做登记。enabled=false 时不注册任何路由。 */
export function apply(ctx: Context, config?: PreviewConfig): void {
  const cfg = normalizeConfig(config);
  if (cfg.enabled === false) return;

  ctx.effect(() => {
    const disposers: Array<() => void> = [];
    try {
      for (const route of makeRoutes(cfg)) {
        disposers.push(ctx.webServer.register(route));
      }
    } catch (error) {
      ctx.logger.error?.("[dsh-web-file-preview] 注册路由失败:", error);
    }
    return () => {
      for (const dispose of disposers) {
        try {
          dispose();
        } catch {
          /* 忽略清理期异常 */
        }
      }
    };
  }, "dsh-web-file-preview: routes");
}

// 路由常量 / 纯函数透出（smoke、客户端契约、诊断共用）。
export { ROUTES, makeRoutes, serveFileRoute, resolveFile, MAX_FILE_PATH_HEADER } from "./routes.ts";
export { previewKindOf } from "./mime.ts";
export { computeGitDiff } from "./git.ts";
// issue #41/#486：basename 兜底纯函数（fdir 通用遍历；issue #423 补强：单测直测变异覆盖）。
export { bareBasenameOf, findUniqueByBasename, DEFAULT_WALK_LIMIT } from "./basename-fallback.ts";
// issue #73：serve token 虚拟伺服（smoke 直测 + 诊断）。
export { serveTokenRoute, allocServeToken, releaseServeToken, serveContentTypeOf, getTokenStore, resetServeTokenStore } from "./routes.ts";
export { createTokenStore, DEFAULT_TOKEN_TTL_MS, DEFAULT_TOKEN_MAX, DEFAULT_ACTIVE_WINDOW_MS, type TokenStore, type TokenStoreOptions } from "./serve-tokens.ts";
// 预览分组判定（单一事实源，宿主/客户端共用；经此透出供 smoke 断言双端一致）。
export { groupOfPath, groupOfExt, extOf, isPreviewablePath, isLikelySingleFilePath, cleanRefChipPath } from "./grouping.ts";
// Markdown 相对/绝对引用展开、fragment 拆分与 openPreview 入参归一（U8 v2 + issue #45/#479；
// 纯函数，经此透出供 smoke 断言）。
export { resolveRelativePath, resolveAbsolutePath, splitReferenceFragment, normalizeBasePath } from "./relpath.ts";
// 点击链接解析纯逻辑（客户端无 DOM 依赖，经此透出供单元测试）。
export { basenameOf, decideGate, resolveFileLink } from "./client/link-resolver.ts";
// 引用 → 预览目标重写决策纯逻辑（issue #45/#479 P2 目录语义；无 DOM 依赖，经此透出供单元测试）。
export { rewriteTarget, dirResolvedPathOf } from "./client/rewrite-target.ts";

