// @ts-nocheck
/**
 * dsh-web-file-preview — unit：预览分组单一事实源（grouping）。
 *
 * 覆盖：extOf（扩展名提取）、groupOfExt / groupOfPath（分组判定）、
 * isPreviewablePath（可预览性）、isLikelySingleFilePath（单文件路径判定）、
 * cleanRefChipPath（@-mention chip 还原）、normalizeConfig（配置归一化）。
 */
import { assert } from "./helpers.ts";
import {
  extOf,
  groupOfExt,
  groupOfPath,
  isPreviewablePath,
  isLikelySingleFilePath,
  cleanRefChipPath,
  normalizeConfig,
  DEFAULT_CONFIG,
} from "../lib/index.js";

// ---------------------------------------------------------------- extOf

assert.equal(extOf("a.txt"), "txt", "普通扩展名");
assert.equal(extOf("dir/file.md"), "md", "带目录的扩展名");
assert.equal(extOf("a.TXT"), "txt", "大写归一化小写");
assert.equal(extOf("a.tar.gz"), "gz", "复合扩展名取最后一段");
assert.equal(extOf("a."), "", "尾点无扩展名返回空");
assert.equal(extOf(".gitignore"), "", "点文件（.gitignore）无扩展名（dot=0 时返回空）");
assert.equal(extOf("Makefile"), "", "无扩展名返回空");
assert.equal(extOf("noext"), "", "无点返回空");
assert.equal(extOf(""), "", "空字符串返回空");
assert.equal(extOf("a/b/c"), "", "有目录无扩展名返回空");
assert.equal(extOf("a/b/.hidden"), "", "隐藏文件无扩展名");

// ---------------------------------------------------------------- groupOfExt

assert.equal(groupOfExt("png"), "image", "png → image");
assert.equal(groupOfExt("jpg"), "image", "jpg → image");
assert.equal(groupOfExt("svg"), "image", "svg → image");
assert.equal(groupOfExt("md"), "md", "md → md");
assert.equal(groupOfExt("markdown"), "md", "markdown → md");
assert.equal(groupOfExt("ts"), "code", "ts → code");
assert.equal(groupOfExt("js"), "code", "js → code");
assert.equal(groupOfExt("py"), "code", "py → code");
assert.equal(groupOfExt("txt"), "text", "txt → text");
assert.equal(groupOfExt("log"), "text", "log → text");
assert.equal(groupOfExt("zip"), "other", "zip → other");
assert.equal(groupOfExt("exe"), "other", "exe → other");
assert.equal(groupOfExt(""), "other", "空扩展名 → other");

// ---------------------------------------------------------------- groupOfPath

assert.equal(groupOfPath("a.png").group, "image", "图片路径分组");
assert.equal(groupOfPath("a.png").ext, "png", "图片路径扩展名回传");
assert.equal(groupOfPath("dir/a.MD").group, "md", "大写 MD 扩展名");
assert.equal(groupOfPath("dir/a.MD").ext, "md", "大写 MD 归一化小写");

// ---------------------------------------------------------------- isPreviewablePath

assert.equal(isPreviewablePath("a.png"), true, "图片可预览");
assert.equal(isPreviewablePath("a.md"), true, "Markdown 可预览");
assert.equal(isPreviewablePath("a.ts"), true, "代码可预览");
assert.equal(isPreviewablePath("a.txt"), true, "文本可预览");
assert.equal(isPreviewablePath("a.zip"), false, "zip 不可预览");
assert.equal(isPreviewablePath("a"), false, "无扩展名不可预览");

// ---------------------------------------------------------------- isLikelySingleFilePath

assert.equal(isLikelySingleFilePath("a/b.ts"), true, "子目录路径可识别");
assert.equal(isLikelySingleFilePath("a b.ts"), false, "文件名含单一空格（无目录分隔符）不识别（U5 语义）");
assert.equal(isLikelySingleFilePath("a/b.ts c/d.ts"), false, "双段含分隔符的拼接非单路径（评审 U5）");
assert.equal(isLikelySingleFilePath("/abs/path.md"), true, "绝对路径可识别");
assert.equal(isLikelySingleFilePath("a.md,b.md"), false, "逗号拼接非单路径");
assert.equal(isLikelySingleFilePath("https://x/a.md"), false, "http 链接排除");
assert.equal(isLikelySingleFilePath("#anchor"), false, "锚点排除");
assert.equal(isLikelySingleFilePath("mailto:a@b.com"), false, "mailto 排除");
assert.equal(isLikelySingleFilePath("a.md\nb.md"), false, "换行拼接排除");
assert.equal(isLikelySingleFilePath("a.md  b.md"), false, "多空格拼接排除");
assert.equal(isLikelySingleFilePath("a.xyz"), false, "不可预览后缀排除");
assert.equal(isLikelySingleFilePath(undefined), false, "undefined 返回 false");
assert.equal(isLikelySingleFilePath(null), false, "null 返回 false");

// ---------------------------------------------------------------- cleanRefChipPath

assert.equal(cleanRefChipPath("@/abs/path.ts", "file"), "/abs/path.ts", "去前导 @ 绝对路径");
assert.equal(cleanRefChipPath('@"a b.ts"', "file"), "a b.ts", "去引号含空格路径");
assert.equal(cleanRefChipPath("node_modules/@scope/x.ts", "file"), "node_modules/@scope/x.ts", "内含 @ 只去一个前导");
assert.equal(cleanRefChipPath("@/a/dir/", "folder"), "/a/dir/", "folder 保留尾 /");
assert.equal(cleanRefChipPath("", "file"), null, "空字符串 → null");
assert.equal(cleanRefChipPath("@", "file"), null, "仅 @ → null");
assert.equal(cleanRefChipPath("@label", "session"), null, "session → null");
assert.equal(cleanRefChipPath("@cmd", "skill"), null, "skill → null");
assert.equal(cleanRefChipPath("@label", "file"), "label", "file 形态只去前导 @");
assert.equal(cleanRefChipPath(undefined, "file"), null, "undefined → null");

// ---------------------------------------------------------------- normalizeConfig

assert.equal(normalizeConfig(undefined).enabled, true, "默认启用");
assert.equal(normalizeConfig(undefined).maxTextBytes, DEFAULT_CONFIG.maxTextBytes, "默认文本上限");
assert.equal(normalizeConfig({ enabled: false }).enabled, false, "enabled 可关闭");
assert.equal(normalizeConfig({ maxTextBytes: 1234 }).maxTextBytes, 1234, "maxTextBytes 合法透传");
assert.equal(normalizeConfig({ maxTextBytes: -1 }).maxTextBytes, DEFAULT_CONFIG.maxTextBytes, "负数丢弃回默认");
assert.equal(normalizeConfig({ maxTextBytes: 0 }).maxTextBytes, DEFAULT_CONFIG.maxTextBytes, "0 丢弃回默认（非正数）");
assert.equal(normalizeConfig({ maxTextBytes: "x" }).maxTextBytes, DEFAULT_CONFIG.maxTextBytes, "非数字丢弃");
assert.equal(normalizeConfig({ enabled: "yes" }).enabled, DEFAULT_CONFIG.enabled, "非布尔 enabled 丢弃回默认");

// @ts-nocheck
/**
 * dsh-web-file-preview — unit：文件链接识别纯逻辑（link-resolver）。
 *
 * 覆盖：basenameOf（归一化比较）、decideGate（点击闸门）、
 * resolveFileLink（凭证优先级/文本后备/芯片旁路/文件夹语义）。
 *
 * 测试全部使用 ResolverNode DTO（最小节点投影），无 DOM 依赖。
 */
import { assert } from "./helpers.ts";
import { basenameOf, decideGate, resolveFileLink } from "../lib/index.js";

/** 构造最小节点投影。 */
function n(text, tag, attrs, parent) {
  return { text, tag, attrs: attrs || {}, parent: parent || null };
}

// ---------------------------------------------------------------- basenameOf

assert.equal(basenameOf("/a/b/c.ts"), "c.ts", "Unix 路径 basename");
assert.equal(basenameOf("C:\\Users\\doc.md"), "doc.md", "Windows 路径 basename");
assert.equal(basenameOf("a/b/c.ts"), "c.ts", "相对路径 basename");
assert.equal(basenameOf("c.ts"), "c.ts", "裸文件名 basename");
assert.equal(basenameOf(""), "", "空字符串返回空");
assert.equal(basenameOf("a/b\\c.ts"), "c.ts", "混合分隔符取最后一段");
assert.equal(basenameOf("  /a/b.ts  "), "b.ts", "首尾空白 trim");
assert.equal(basenameOf("a/b.TS"), "b.ts", "小写归一化");

// ---------------------------------------------------------------- decideGate

function probe(sel) {
  return { matches: (s) => s === sel };
}

assert.equal(decideGate(probe("[data-dsh-no-preview]"), ["[data-chat-flow]"]), "pass", "豁免属性优先放行");
assert.equal(decideGate(probe("[data-chat-flow]"), ["[data-chat-flow]"]), "inspect", "作用域匹配进入解析");
assert.equal(decideGate(probe("[data-chat-anchor-key]"), ["[data-chat-flow]", "[data-chat-anchor-key]"]), "inspect", "多作用域之一匹配");
assert.equal(decideGate(probe("unknown"), ["[data-chat-flow]"]), "pass", "无匹配放行");
assert.equal(decideGate(probe("[data-dsh-no-preview]"), []), "pass", "豁免属性无需作用域即放行");
assert.equal(decideGate(probe("unknown"), []), "pass", "无作用域无豁免放行");

// ---------------------------------------------------------------- resolveFileLink

// 凭证优先：data-ref-chip="file" 的 title 立即返回
assert.deepEqual(resolveFileLink(n("", "SPAN", { "data-ref-chip": "file", title: "@/abs/path.ts" })),
  { path: "/abs/path.ts", kind: "file" }, "chip file 权威凭证");

// chip folder 返回 folder 语义
assert.deepEqual(resolveFileLink(n("", "SPAN", { "data-ref-chip": "folder", title: "@/a/dir/" })),
  { path: null, kind: "folder" }, "chip folder 提示语义");

// chip session/skill 跳过本节点
assert.equal(resolveFileLink(n("", "SPAN", { "data-ref-chip": "session" })), null, "chip session 跳过返回 null");

// A[href] 凭证
assert.deepEqual(
  resolveFileLink(n("", "A", { href: "/abs/path.ts" })),
  { path: "/abs/path.ts", kind: "file" },
  "A[href] 凭证",
);

// title 凭证
assert.deepEqual(
  resolveFileLink(n("", "SPAN", { title: "/abs/path.ts" })),
  { path: "/abs/path.ts", kind: "file" },
  "title 凭证",
);

// 文本后备：无凭证时回退文本命中
assert.deepEqual(
  resolveFileLink(n("src/a.ts", "CODE", {}, null)),
  { path: "src/a.ts", kind: "file" },
  "CODE 文本回退",
);

// 凭证与文本命中 basename 一致 → 采信凭证
assert.deepEqual(
  resolveFileLink(n("a.ts", "SPAN", {}, n("", "SPAN", { title: "/abs/path/a.ts" }, null))),
  { path: "/abs/path/a.ts", kind: "file" },
  "凭证与文本 basename 一致则采信凭证完整路径",
);

// 凭证与文本命中 basename 不一致 → 跳过凭证继续向上
assert.deepEqual(
  resolveFileLink(n("b.ts", "SPAN", {}, n("", "SPAN", { title: "/abs/path/a.ts" }, null))),
  { path: "b.ts", kind: "file" },
  "凭证与文本 basename 不一致则跳过凭证，回退文本",
);

// 纯文本路径 > 1024 字符不命中
assert.deepEqual(
  resolveFileLink(n("a".repeat(1025), "CODE", {}, null)),
  null,
  "超长文本不命中",
);

// 非 path-like 文本不命中
assert.equal(resolveFileLink(n("a.xyz", "CODE", {}, null)), null, "不可预览后缀文本不命中");

// 无 title / href / chip 的非 CODE/SPAN/A/BUTTON 标签不提取文本
assert.equal(resolveFileLink(n("a.ts", "DIV", {}, null)), null, "DIV 文本不命中");

// 多层嵌套：session chip 跳过本层祖先，但祖先 title 凭证仍需与文本 basename 一致
assert.deepEqual(
  resolveFileLink(n("a.ts", "SPAN", {}, n("", "SPAN", { "data-ref-chip": "session" }, n("", "SPAN", { title: "/abs/path/a.ts" }, null)))),
  { path: "/abs/path/a.ts", kind: "file" },
  "session chip 跳过本层，祖先 title 凭证与文本 basename 一致则采信",
);

// 祖先 title 凭证与文本 basename 不一致 → 回退文本命中
assert.deepEqual(
  resolveFileLink(n("a.ts", "SPAN", {}, n("", "SPAN", { "data-ref-chip": "session" }, n("", "SPAN", { title: "/abs/other/b.ts" }, null)))),
  { path: "a.ts", kind: "file" },
  "祖先 title 凭证 basename 不一致则跳过，回退文本命中",
);

// @ts-nocheck
/**
 * dsh-web-file-preview — unit：Markdown 相对引用路径展开（relpath）。
 *
 * 覆盖：resolveRelativePath 全部语义分支——同目录、./、../、query/fragment 丢弃、
 * %20 解码、绝对路径/协议相对/外域/data URI 不展开、/api/ 幂等保持、空/非法引用；
 * issue #45 新增：resolveAbsolutePath 绝对路径规范化分支与
 * splitReferenceFragment fragment 剥离分支。
 */
import { assert } from "./helpers.ts";
import { resolveRelativePath, resolveAbsolutePath, splitReferenceFragment, normalizeBasePath } from "../lib/index.js";

const BASE = "/home/u/work/src/a.md";

// 正常展开
assert.equal(resolveRelativePath(BASE, "img.png"), "/home/u/work/src/img.png", "同目录");
assert.equal(resolveRelativePath(BASE, "./img.png"), "/home/u/work/src/img.png", "./ 相对引用");
assert.equal(resolveRelativePath(BASE, "../b.md"), "/home/u/work/b.md", "../ 上级目录");
assert.equal(resolveRelativePath(BASE, "docs/../c.md"), "/home/u/work/src/c.md", ".. 规范化");
assert.equal(resolveRelativePath(BASE, "sub/d.md"), "/home/u/work/src/sub/d.md", "子目录");

// query / fragment 丢弃
assert.equal(resolveRelativePath(BASE, "a.md?x=1"), "/home/u/work/src/a.md", "query 丢弃");
assert.equal(resolveRelativePath(BASE, "a.md#sec"), "/home/u/work/src/a.md", "fragment 丢弃");
assert.equal(resolveRelativePath(BASE, "a.md?x=1#sec"), "/home/u/work/src/a.md", "query+fragment 丢弃");

// 编码解码
assert.equal(resolveRelativePath(BASE, "%E4%B8%AD.md"), "/home/u/work/src/中.md", "UTF-8 编码解码");
assert.equal(resolveRelativePath(BASE, "file%20name.md"), "/home/u/work/src/file name.md", "空格编码解码");
assert.equal(resolveRelativePath(BASE, "%25encoded.md"), "/home/u/work/src/%encoded.md", "%25 双层层解码为 %（URL 解析 + decodeURIComponent 各一次）");

// 不展开分支
assert.equal(resolveRelativePath(BASE, "/etc/passwd"), null, "绝对路径 / 不展开");
assert.equal(resolveRelativePath(BASE, "https://x/a.md"), null, "http 链接不展开");
assert.equal(resolveRelativePath(BASE, "//cdn/x.png"), null, "协议相对不展开");
assert.equal(resolveRelativePath(BASE, "data:image/png;base64,AA=="), null, "data URI 不展开");
assert.equal(resolveRelativePath(BASE, "#sec"), null, "纯锚点不展开");
assert.equal(resolveRelativePath(BASE, "mailto:test@example.com"), null, "mailto 不展开");
assert.equal(resolveRelativePath(BASE, "file:///etc/passwd"), null, "file:// 协议不展开");

// 幂等：/api/ 前缀
assert.equal(resolveRelativePath(BASE, "/api/dsh-file-preview/file?path=/x"), null, "/api/ 前缀幂等保持");

// 空/非法
assert.equal(resolveRelativePath(BASE, ""), null, "空字符串返回 null");
assert.equal(resolveRelativePath(BASE, undefined), null, "undefined 返回 null");
assert.equal(resolveRelativePath(BASE, null), null, "null 返回 null");

// Windows 风格路径
assert.equal(resolveRelativePath("C:\\Users\\me\\doc.md", "img.png"), "/C:/Users/me/img.png", "Windows 基路径反斜杠转正斜杠（带前导 /，跟随实现）");

// 深层嵌套
assert.equal(resolveRelativePath(BASE, "../../other/file.md"), "/home/u/other/file.md", "../../ 两级上跳");

// baseFile 不含目录（裸文件名）→ URL 构造异常，返回 null
assert.equal(resolveRelativePath("readme.md", "img.png"), null, "裸文件名基路径无法解析，返回 null");

// ------------------------------------------------------------ issue #45：绝对路径展开（resolveAbsolutePath）

assert.equal(resolveAbsolutePath("/home/u/proj/docs/design.md"), "/home/u/proj/docs/design.md", "绝对路径原样保留");
assert.equal(resolveAbsolutePath("/home/u/proj/docs/../docs/design.md"), "/home/u/proj/docs/design.md", ".. 规范化");
assert.equal(resolveAbsolutePath("/a/b/./c.md"), "/a/b/c.md", ". 规范化");
assert.equal(resolveAbsolutePath("/x/%E4%B8%AD%E6%96%87.md"), "/x/中文.md", "UTF-8 编码解码");
assert.equal(resolveAbsolutePath("/x/my file.md"), "/x/my file.md", "含空格路径原样");
assert.equal(resolveAbsolutePath("//cdn/x.png"), null, "// 协议相对形态拒绝");
assert.equal(resolveAbsolutePath("rel/a.md"), null, "非 / 开头拒绝");
assert.equal(resolveAbsolutePath(""), null, "空字符串拒绝");
assert.equal(resolveAbsolutePath(undefined), null, "undefined 拒绝");
assert.equal(resolveAbsolutePath(null), null, "null 拒绝");

// ------------------------------------------------------------ issue #45：fragment 剥离（splitReferenceFragment）

assert.deepEqual(splitReferenceFragment("./f.md#g"), { ref: "./f.md", fragment: "g" }, "相对引用带锚点拆分");
assert.deepEqual(splitReferenceFragment("b.md"), { ref: "b.md", fragment: null }, "无锚点 fragment 为 null");
assert.deepEqual(splitReferenceFragment("#section"), { ref: "", fragment: "section" }, "纯锚点 ref 为空串");
assert.deepEqual(splitReferenceFragment("a.md?x=1#sec"), { ref: "a.md?x=1", fragment: "sec" }, "query+锚点拆分");
assert.deepEqual(splitReferenceFragment("a.md#"), { ref: "a.md", fragment: null }, "空锚点视为无 fragment");
assert.deepEqual(splitReferenceFragment("a.md#%E4%B8%AD"), { ref: "a.md", fragment: "中" }, "锚点 %XX 解码一次");
assert.deepEqual(splitReferenceFragment("a.md#%zz"), { ref: "a.md", fragment: "%zz" }, "非法编码锚点原样保留");

// ------------------------------------------------------------ issue #479：openPreview 入参归一（normalizeBasePath）

const CWD = "/home/u/proj";
// —— 相对 path + 绝对 cwd → 绝对形态（核心修复）
assert.equal(normalizeBasePath("docs/a.md", CWD), "/home/u/proj/docs/a.md", "相对+绝对 cwd → 绝对");
assert.equal(normalizeBasePath("./img.png", CWD), "/home/u/proj/img.png", "./ 前缀归一");
assert.equal(normalizeBasePath("docs/../b.md", CWD), "/home/u/proj/b.md", ".. 归一由 URL 规范化");
assert.equal(normalizeBasePath("docs/中 文/图 片.png", CWD), "/home/u/proj/docs/中 文/图 片.png", "空格+中文保留");
assert.equal(normalizeBasePath("docs\\sub\\a.md", CWD), "/home/u/proj/docs\\sub\\a.md", "反斜杠相对路径归一（POSIX 下作为普通字符，跟随实现）");
// —— 特殊字符文件名（评审必改项：段级转义防截断/错解码）
assert.equal(normalizeBasePath("docs/a#b.md", CWD), "/home/u/proj/docs/a#b.md", "含 # 文件名保留（URL 不吞 fragment）");
assert.equal(normalizeBasePath("docs/a?b.md", CWD), "/home/u/proj/docs/a?b.md", "含 ? 文件名保留（URL 不吞 query）");
assert.equal(normalizeBasePath("docs/a%20b.md", CWD), "/home/u/proj/docs/a%20b.md", "字面 %20 保留（不全解码为空格）");
assert.equal(normalizeBasePath("docs/a%2Fb.md", CWD), "/home/u/proj/docs/a%2Fb.md", "字面 %2F 保留（不当分隔符）");
assert.equal(normalizeBasePath("docs/%E4%B8%AD.md", CWD), "/home/u/proj/docs/%E4%B8%AD.md", "已编码输入单解一致（URL 解码一次）");
// —— 纯裸名不归一（保留服务端 #41 basename 兜底可达）
assert.equal(normalizeBasePath("AGENTS.md", CWD), "AGENTS.md", "纯裸名不归一（#41 兜底可达）");
assert.equal(normalizeBasePath("solo", CWD), "solo", "无扩展名裸名同样不归一");
// —— 绝对形态原样（幂等基）
assert.equal(normalizeBasePath("/abs/x.md", CWD), "/abs/x.md", "绝对路径原样");
assert.equal(normalizeBasePath("~/x.md", CWD), "~/x.md", "~/ 家目录语义原样（服务端 untildify）");
assert.equal(normalizeBasePath("~\\x.md", CWD), "~\\x.md", "~\\ 家目录反斜杠形态原样");
assert.equal(normalizeBasePath("C:\\x\\y.md", CWD), "C:\\x\\y.md", "盘符绝对原样");
assert.equal(normalizeBasePath("//cdn/x.png", CWD), "//cdn/x.png", "协议相对原样");
assert.equal(normalizeBasePath("https://x/a.md", CWD), "https://x/a.md", "scheme 原样");
// —— cwd 异常/缺失 → 原样（显式分支）
assert.equal(normalizeBasePath("docs/a.md", undefined), "docs/a.md", "无 cwd → 原样");
assert.equal(normalizeBasePath("docs/a.md", ""), "docs/a.md", "空 cwd → 原样");
assert.equal(normalizeBasePath("docs/a.md", "work/src"), "docs/a.md", "相对 cwd → 原样（显式分支）");
assert.equal(normalizeBasePath("", CWD), "", "空路径 → 原样");
// —— cwd 尾斜杠 strip（防 // 双斜杠污染）
assert.equal(normalizeBasePath("docs/a.md", "/home/u/proj/"), "/home/u/proj/docs/a.md", "cwd 尾斜杠 → 无双斜杠");
// —— 盘符 cwd + 相对 path → C:/ 形态（win32 round-trip 正确，评审 F3.1 必改项）
assert.equal(normalizeBasePath("docs/a.md", "C:\\Users\\me"), "C:/Users/me/docs/a.md", "盘符 cwd + 相对 → C:/... 形态（去前导 /）");
assert.equal(normalizeBasePath("docs/a.md", "C:\\Users\\me\\"), "C:/Users/me/docs/a.md", "盘符 cwd 尾斜杠同样 strip");
// —— 幂等（入口归一天然幂等）
{
  const once = normalizeBasePath("docs/a.md", CWD);
  assert.equal(normalizeBasePath(once, CWD), once, "归一幂等：二次调用不变");
}

// @ts-nocheck
/**
 * dsh-web-file-preview — unit：路由、apply 扩散函数、readErrorCode/readErrorText
 * 纯函数分支。
 *
 * 覆盖：readErrorCode（EACCES → 500 间接覆盖）、readErrorText（同）、
 * diffRoute 围栏（403/405/400/200）、apply（启用/禁用/异常/清理）。
 *
 * readErrorCode/readErrorText 未从 lib 导出，通过 chmod 000 使 stat 之后
 * readFile 失败（EACCES）触发 serveFileRoute 的 catch 分支间接覆盖。
 */
import { assert } from "./helpers.ts";
import { mkdtempSync, writeFileSync, rmSync, chmodSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ROUTES, makeRoutes, serveFileRoute, apply, serveContentTypeOf, allocServeToken, releaseServeToken, serveTokenRoute } from "../lib/index.js";

// ---------------------------------------------------------------- 帮助函数

function fakeReq(method, url, remoteAddress, host = "127.0.0.1") {
  return { method, url, headers: { host }, socket: { remoteAddress } };
}
function fakeRes() {
  const calls = { status: 0, headers: {}, data: null };
  const listeners = {};
  return {
    _calls: calls,
    writeHead(status, headers) { calls.status = status; calls.headers = headers || {}; return this; },
    end(data) { if (data !== undefined) calls.data = data; },
    write(chunk) { calls.data = calls.data === null ? Buffer.from(chunk) : Buffer.concat([Buffer.from(calls.data), Buffer.from(chunk)]); return true; },
    on(evt, fn) { (listeners[evt] = listeners[evt] || []).push(fn); return this; },
  };
}
function rawReqForFiles(headers = {}) {
  return { headers };
}

// 检查是否以 root 运行（chmod 000 无效）
const isRoot = typeof process.getuid === "function" && process.getuid() === 0;

const root = mkdtempSync(join(tmpdir(), "fwp-ut-"));
try {
  writeFileSync(join(root, "pic.png"), Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
  writeFileSync(join(root, "doc.txt"), "hello", "utf8");

  // ================================================================
  // readErrorCode / readErrorText（通过 chmod 000 触发 readFile 失败）
  // ================================================================

  if (!isRoot) {
    chmodSync(join(root, "pic.png"), 0o000);
    const url = `http://127.0.0.1${ROUTES.file}?cwd=${encodeURIComponent(root)}&path=pic.png`;
    const res = fakeRes();
    await serveFileRoute(res, rawReqForFiles(), new URL(url), {});
    assert.equal(res._calls.status, 500, "chmod 000 图片 → 500（readErrorCode EACCES）");
    assert.equal(JSON.parse(res._calls.data).error, "read failed", "readErrorText EACCES → 'read failed'");
    chmodSync(join(root, "pic.png"), 0o644);

    chmodSync(join(root, "doc.txt"), 0o000);
    const url2 = `http://127.0.0.1${ROUTES.file}?cwd=${encodeURIComponent(root)}&path=doc.txt`;
    const res2 = fakeRes();
    await serveFileRoute(res2, rawReqForFiles(), new URL(url2), {});
    assert.equal(res2._calls.status, 500, "chmod 000 文本 → 500（readErrorCode 文本分支）");
    assert.equal(JSON.parse(res2._calls.data).error, "read failed", "文本 readErrorText");
    chmodSync(join(root, "doc.txt"), 0o644);
  } else {
    console.log("  (跳过 readErrorCode EACCES 测试：以 root 运行，chmod 000 无效)");
  }

  // ================================================================
  // diffRoute 围栏与响应
  // ================================================================

  const routes = makeRoutes({});
  const diffHandler = routes[1].handler;

  // 非回环 → 403
  {
    const res = fakeRes();
    await diffHandler(fakeReq("GET", ROUTES.diff + "?cwd=/tmp&path=a", "8.8.8.8"), res);
    assert.equal(res._calls.status, 403, "diff 非回环 403");
  }
  // 方法非 GET → 405
  {
    const res = fakeRes();
    await diffHandler(fakeReq("POST", ROUTES.diff + "?cwd=/tmp&path=a", "127.0.0.1"), res);
    assert.equal(res._calls.status, 405, "diff 非 GET 405");
  }
  // 缺 cwd → 400
  {
    const res = fakeRes();
    await diffHandler(fakeReq("GET", ROUTES.diff + "?path=a", "127.0.0.1"), res);
    assert.equal(res._calls.status, 400, "diff 缺 cwd 400");
  }
  // 缺 path → 400
  {
    const res = fakeRes();
    await diffHandler(fakeReq("GET", ROUTES.diff + "?cwd=/tmp", "127.0.0.1"), res);
    assert.equal(res._calls.status, 400, "diff 缺 path 400");
  }
  // 正常请求（非 git 目录 → not-git → 200）
  {
    const res = fakeRes();
    await diffHandler(
      fakeReq("GET", `${ROUTES.diff}?cwd=${encodeURIComponent(root)}&path=doc.txt`, "127.0.0.1"),
      res,
    );
    assert.equal(res._calls.status, 200, "diff 非 git 目录 → 200");
    const payload = JSON.parse(res._calls.data);
    assert.equal(payload.ok, true, "diff 响应含 ok:true");
    assert.equal(payload.reason, "not-git", "diff 非 git 目录 → not-git");
  }

  // ================================================================
  // apply
  // ================================================================

  // apply 启用 → effect 回调执行，7 条路由注册（file/diff/health/mermaid/alloc/serve/release），清理正常
  {
    const disposerCalls = [];
    const fakeCtx = {
      effect: (cb) => {
        const dispose = cb();
        disposerCalls.push(dispose);
      },
      webServer: {
        register: (route) => {
          disposerCalls.push(route.path);
          return () => { disposerCalls.push("disposed"); };
        },
      },
      logger: { error: () => {} },
    };
    apply(fakeCtx, {});
    // 验证 effect 回调已执行、路由已注册
    const routePaths = disposerCalls.filter((x) => typeof x === "string");
    assert.equal(routePaths.length, 7, "apply 启用 → 7 条路由注册（#104 mermaid + #73 serve 三件套）");
    assert.ok(routePaths.includes(ROUTES.file), "file 路由已注册");
    assert.ok(routePaths.includes(ROUTES.diff), "diff 路由已注册");
    assert.ok(routePaths.includes(ROUTES.health), "health 路由已注册");
    assert.ok(routePaths.includes(ROUTES.mermaid), "#104 mermaid 路由已注册");
    assert.ok(routePaths.includes(ROUTES.serve), "#73 serve 路由已注册");
    assert.ok(routePaths.includes(ROUTES.alloc), "#73 alloc 路由已注册");
    assert.ok(routePaths.includes(ROUTES.release), "#73 release 路由已注册");
    // 触发清理
    const cleanup = disposerCalls.find((x) => typeof x === "function");
    if (cleanup) cleanup();
    const disposedCount = disposerCalls.filter((x) => x === "disposed").length;
    assert.equal(disposedCount, 7, "disposer 清理 7 条路由");
  }

  // apply 禁用 → 不注册任何路由，effect 不被调用
  {
    let effectCalled = false;
    const fakeCtx = {
      effect: () => { effectCalled = true; },
      webServer: { register: () => () => {} },
      logger: { error: () => {} },
    };
    apply(fakeCtx, { enabled: false });
    assert.equal(effectCalled, false, "apply 禁用 → effect 不被调用");
  }

  // 注册路由失败 → logger.error 被调用（catch 分支）
  {
    let loggerError = null;
    let disposeFn = null;
    const fakeCtx = {
      effect: (cb) => { disposeFn = cb(); },
      webServer: { register: () => { throw new Error("register failed"); } },
      logger: { error: (...args) => { loggerError = args; } },
    };
    apply(fakeCtx, {});
    assert.ok(loggerError !== null, "apply 异常 → logger.error 被调用");
    assert.match(loggerError[0], /注册路由失败/, "logger.error 消息含失败提示");
    // 异常后清理仍可被调用（空数组迭代）
    if (disposeFn) disposeFn();
  }

  // ================================================================
  // serve 三件套轻分支（#423 补强：serveContentTypeOf / release / alloc / serve 缺参）
  // ================================================================

  // serveContentTypeOf：html/htm → text/html；已知 ext 走 mime；未知 → octet-stream
  {
    assert.equal(serveContentTypeOf("page.html"), "text/html; charset=utf-8", "serveContentTypeOf html");
    assert.equal(serveContentTypeOf("page.HTM"), "text/html; charset=utf-8", "serveContentTypeOf htm（大小写归一）");
    assert.equal(serveContentTypeOf("a.css"), "text/css", "serveContentTypeOf 已知 ext（css）");
    assert.equal(serveContentTypeOf("x.q7x9z"), "application/octet-stream", "serveContentTypeOf 未知 ext → octet-stream");
  }

  // release 缺参 → 400；未知 token 幂等 200
  {
    const res = fakeRes();
    releaseServeToken(res, new URL(`http://127.0.0.1${ROUTES.release}`));
    assert.equal(res._calls.status, 400, "release 缺 token → 400");
    const res2 = fakeRes();
    releaseServeToken(res2, new URL(`http://127.0.0.1${ROUTES.release}?token=deadbeefdeadbeefdeadbeefdeadbeef`));
    assert.equal(res2._calls.status, 200, "release 未知 token 幂等 200");
  }

  // alloc 缺 path → 400；非 html → 400；不存在 → 404
  {
    const res = fakeRes();
    await allocServeToken(res, new URL(`http://127.0.0.1${ROUTES.alloc}?cwd=${encodeURIComponent(root)}`), {});
    assert.equal(res._calls.status, 400, "alloc 缺 path → 400");
    const res2 = fakeRes();
    await allocServeToken(res2, new URL(`http://127.0.0.1${ROUTES.alloc}?cwd=${encodeURIComponent(root)}&path=doc.txt`), {});
    assert.equal(res2._calls.status, 400, "alloc 非 html → 400");
    const res3 = fakeRes();
    await allocServeToken(res3, new URL(`http://127.0.0.1${ROUTES.alloc}?cwd=${encodeURIComponent(root)}&path=nope.html`), {});
    assert.equal(res3._calls.status, 404, "alloc 不存在 → 404");
  }

  // serve 未知 token → 404（不泄露区分信息）
  {
    const res = fakeRes();
    await serveTokenRoute(res, fakeReq("GET", `${ROUTES.serve}/deadbeefdeadbeefdeadbeefdeadbeef/index.html`, "127.0.0.1"), new URL(`http://127.0.0.1${ROUTES.serve}/deadbeefdeadbeefdeadbeefdeadbeef/index.html`), {});
    assert.equal(res._calls.status, 404, "serve 未知 token → 404");
  }

  console.log("PASS unit-routes");
} finally {
  rmSync(root, { recursive: true, force: true });
}

// @ts-nocheck
/**
 * dsh-web-file-preview — unit：serve token 生命周期（serve-tokens 纯逻辑，无 node:http 依赖）。
 *
 * 覆盖：alloc 全生命周期、get 命中刷新 idle 计时、TTL 超时懒回收、时钟回拨 cutoff
 * 兜底、release 幂等、size / snapshot、LRU 不淘汰活跃、全活跃拒绝、达上限腾位——
 * 与 smoke #73 B 组断言互补（smoke 走真实路由，本文件直测 store 分支）。
 */
import { assert } from "./helpers.ts";
import { createTokenStore } from "../lib/index.js";

// ---------------------------------------------------------------- alloc / get 基础生命周期

{
  let now = 1_000;
  const store = createTokenStore({ now: () => now, ttlMs: 100, maxTokens: 3, activeWindowMs: 20 });
  const token = store.alloc("/root/a");
  assert.equal(typeof token, "string", "alloc 返回 token");
  assert.equal(token.length, 32, "token 为 128-bit hex");
  assert.equal(store.size(), 1, "alloc 后 size=1");
  assert.deepEqual(store.snapshot().get(token), { root: "/root/a", lastHit: 1_000 }, "snapshot 保存完整条目");
  const hit = store.get(token);
  assert.ok(hit !== undefined && hit.root === "/root/a", "get 命中返回 root");
  // 命中刷新 idle 计时：推进到临近 TTL 仍存活，且 lastHit 被刷新
  now = 1_015;
  assert.equal(store.get(token).lastHit, 1_015, "get 命中刷新 lastHit（idle 语义）");
  // snapshot 是独立副本：外部删改不影响 store
  const snap = store.snapshot();
  snap.delete(token);
  assert.equal(store.size(), 1, "snapshot 删改不影响 store");
  // 闲置超过 TTL：访问时懒回收（lastHit 最后一次 get 刷新为 1_015；
  // TTL=100 → 需 now ≥ 1_116 才满足 lastHit < cutoff，即 idle 满 100ms）
  now = 1_116;
  assert.equal(store.get(token), undefined, "闲置超过 TTL → 访问时回收");
  assert.equal(store.size(), 0, "TTL 回收减少 size");
  assert.equal(store.release(token), false, "释放未知 token 返回 false");
  assert.equal(store.release(token), false, "release 幂等（第二次仍 false）");
}

// ---------------------------------------------------------------- 时钟回拨 cutoff 兜底

{
  let now = 2_000;
  const store = createTokenStore({ now: () => now, ttlMs: 100, maxTokens: 2, activeWindowMs: 20 });
  const token = store.alloc("/root/clock");
  // 推进时钟使 maxClockSeen=2_050（alloc 已令 maxClockSeen=2_000，get 后 2_050）
  now = 2_050;
  assert.ok(store.get(token), "推进时钟后 token 可命中");
  // 回拨到 alloc 之前：cutoff=maxClockSeen-TTL=1_950，entry.lastHit=2_050 不 < 1_950
  // ——证明 cutoff 用见过的最大时钟而非当前时钟，回拨不会把"未来"的 token 复活
  now = 1_500;
  const afterRewind = store.get(token);
  assert.ok(afterRewind !== undefined, "回拨后 token 仍按 maxClockSeen 截止不被复活");
  assert.equal(afterRewind.lastHit, 1_500, "回拨后 lastHit 被本次 get 写成回拨后的时间");
}

// ---------------------------------------------------------------- LRU：不淘汰活跃 / 淘汰最久非活跃 / 达上限腾位

{
  let now = 10_000;
  const store = createTokenStore({ now: () => now, ttlMs: 10_000, maxTokens: 2, activeWindowMs: 10 });
  const old = store.alloc("/root/old");
  now += 20;
  const active = store.alloc("/root/active");
  assert.equal(store.size(), 2, "达到上限前两个 token 并存");
  now += 1;
  assert.ok(store.get(active), "活跃 token 命中（刷新 idle）");
  const replacement = store.alloc("/root/new");
  assert.ok(replacement, "达上限且有非活跃项 → 腾位成功");
  assert.equal(store.get(old), undefined, "LRU 淘汰最久未用且非活跃的 token");
  assert.ok(store.get(active), "LRU 不淘汰活跃 token");
  assert.equal(store.size(), 2, "淘汰后 size 仍为上限");
}

// ---------------------------------------------------------------- 全活跃拒绝 / 活跃窗口过后可腾位

{
  let now = 20_000;
  const store = createTokenStore({ now: () => now, ttlMs: 10_000, maxTokens: 2, activeWindowMs: 100 });
  const a = store.alloc("/root/a");
  const b = store.alloc("/root/b");
  assert.equal(store.alloc("/root/c"), null, "全部活跃且达上限 → 拒绝新分配");
  now += 101; // 两个 token 都老化出活跃窗口 → 下次分配可淘汰腾位
  assert.ok(store.alloc("/root/c"), "活跃窗口过去后 → 可淘汰腾位分配");
  // 腾位时淘汰最久未用的非活跃 a（a/b 同为 lastHit=20_000，按插入序先淘汰 a）
  assert.equal(store.get(a), undefined, "腾位时淘汰最久未用且非活跃的 a");
  assert.equal(store.release(a), false, "a 已淘汰 → release false");
  assert.equal(store.release(b), true, "release 存在 token（b）→ true");
  assert.equal(store.release(b), false, "release 同 token 第二次 → false");
}

console.log("PASS unit-serve-tokens");

